import type { FilterExpression } from '@wix/sdk-types'
import type { WixDataItem, WixDataQuerySpec } from './types'
import type { WixDataPatchOptions } from './WixDataPatch'

/**
 * Options builder for patch operations.
 *
 * Use this builder to configure patch behavior such as hooks suppression,
 * and conditional patching.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataPatchOptionsBuilder {
  /**
   * Sets whether to suppress patch hooks.
   *
   * When `true`, the patch runs without triggering hooks.
   */
  withSuppressHooks(value: boolean): WixDataPatchOptionsBuilder
  /**
   * Sets whether to include draft items when patching an item.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataPatchOptionsBuilder
  /**
   * Sets the condition that determines whether to patch the item.
   */
  withCondition(
    value: FilterExpression<WixDataItem, WixDataQuerySpec>
  ): WixDataPatchOptionsBuilder
  /**
   * Builds the patch options object.
   */
  build(): WixDataPatchOptions
}

class WixDataPatchOptionsBuilderImpl implements WixDataPatchOptionsBuilder {
  constructor(private readonly options: WixDataPatchOptions = {}) {}

  withSuppressHooks(value: boolean): WixDataPatchOptionsBuilder {
    return this.copy({ suppressHooks: value })
  }

  withShowDrafts(value: boolean): WixDataPatchOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  withCondition(
    value: FilterExpression<WixDataItem, WixDataQuerySpec>
  ): WixDataPatchOptionsBuilder {
    return this.copy({ condition: value.filter })
  }

  build(): WixDataPatchOptions {
    return {
      ...this.options,
    }
  }

  private copy(options: WixDataPatchOptions): WixDataPatchOptionsBuilder {
    return new WixDataPatchOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new patch options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create a patch options builder"
 * import { items, PatchOptionsBuilder, Filter } from '@wix/data'
 *
 * const options = PatchOptionsBuilder()
 *   .withSuppressHooks(true)
 *   .withCondition(Filter('status').eq('active'))
 *   .build()
 *
 * const item = await items.patch('myCollection', 'someId', option)
 * ```
 */
export const PatchOptionsBuilder: () => WixDataPatchOptionsBuilder = () =>
  new WixDataPatchOptionsBuilderImpl()
